# 　{报表日}/{类别}/{种子} 等占位符，由 mingcheng 渲染后再落格。
#
# ── 单张表的 11 个版式键（22 张表结构完全一致，逐键语义）─────────────────────────
# dims             (行数, 列数)：版式坐标系上限，任何地址都不会越过它
# lie_kuan         {列号: 列宽}：列宽单位「字符」（Excel 宽度口径），如 62.0
