# freeze           冻结窗格锚点：'A4' = 滚动时前 3 行（及 A 列）常驻，None = 不冻结
# biaoqian         {'地址': '文本'}：静态标签，含 {xxx} 的为生成时替换的占位符
# shuzhi_wei       金额格清单：按「两位小数 + 千分位 + 零值占位」显示
# ge_ys            {'地址': 样式号}：单格样式覆盖，样式号 = yangshi 下标（0 起）
# lie_ys           {列字母: 样式号}：整列默认样式，'*' 是未单列列的兜底
# yangshi          [17 元组…]：样式表，字段序见第 1~10 行文件头「样式签名字段序」
