 # 2/6 销售费用：预算基础三费里最细的一张，480 行 × 51 列，带量价结构 ──────────────────
 # 列：A=12.6 一级科目（员工费用 / 差旅费 / 业务招待费 …，纵向合并成块）、B=28 二级科目
 # 　（工资 / 机票火车票 / 住宿费 …）、C~N=2027-01~2027-12（12 个月金额）、O=小计、
 # 　P~V 元字段区、AX/AY 元字段键值区。
 # 合并：13 组 hebing 把 A 列一级科目纵向合并（A4:A10 员工费用、A11:A20 差旅费、A21:A24、
 # 　A25:B25、A26:B26、A27:B27、A29:A30、A31:A32、A33:B33、A34:B34、A35:B35、A36:B36、
 # 　A2:B3 表头块）；合并只影响显示，金额仍写在合并区最上 / 最左格。
 # 表头：A1「销售费用」、AX1/AY1 记模板版本「标准输入模板/1.0.5」、A2「项目」、
 # 　C2「预算基础（月度，元）」、C3~N3 = 2027-01~2027-12、O3「小计」。
 # 量价区：第 341~353 行是「…数量」行（住宿费数量 / 交通费数量 / 差旅补贴数量 / 业务招待
 # 　费数量 / 市内交通费数量 / 调研费用数量 / 手续费数量 / 利息收入数量 / 利息支出数量 /
 # 　车船税数量 / 印花税数量 / 其他数量），是「单价 × 数量 = 金额」业务口径的落点。
 # 公式链：C~N 12 个月 → O 小计 → 费用表月度汇总 → 利润表第 8 行「销售费用」。
 # 元字段：P4 起逐行给 EXP 编码（EXP1.004…）/ 数据版本号 / 口径标记 / 生效周期，把「哪一
 # 　行是哪个科目、哪一期生效」写进表本身；导入时按行号 + EXP 双键对齐。
 # 样式：yangshi 8 个（标题 / 元字段 / 一级科目 / 二级科目 / 金额 / 小计 …）、lie_ys 25 条、
 # 　ge_ys 1460 条逐格样式（其中 1101 个是金额格）、shuzhi_wei 1101 个、freeze A4。
