 # 5/6 摊销明细：唯一一张「纵向资产台账 + 横向月份矩阵」的二维表，29 行 × 51 列 ───────────
 # 上半区（第 1~6 行）是单资产汇总：摊销资产原值 / 摊销月数 / 本月摊销 / 累计已摊销 /
 # 　尚未摊销 / 摊销起始日（B6 = 2027-01-01），只关心总数的读取方直接取这 6 格。
 # 台账区（第 8 行『摊销台账区（契约v1.1·多资产台账与月度矩阵）』）：第 9 行表头——资产
 # 　名称 / 费用归属表 / 部门 / 起始月（YYYY-MM）/ 原值 / 摊销月数 / 月摊销额；第 19 行起
 # 　是「资产＼月份」矩阵，B19~M19 = 1 月~12 月、N19 = 年合计；第 29 行合计。
 # 公式链：每行「原值 ÷ 摊销月数 = 月摊销额」→ 按起始月铺到 B~M 对应列 → 行内年合计 N →
 # 　第 29 行合计；摊销额再回填管理费用 / 销售费用的「折旧及摊销」行，是费用表的底稿。
 # 版式特点：hang_gao 与 hebing 都是空字典、freeze 为 None——不锁行高、不合并、不冻结，行高
 # 　一律走默认值；样式改由 30 条 lie_ys 与 119 条 ge_ys 逐列逐格指定（资产条数不固定，
 # 　靠逐格套样式而不是靠版式锚点）。
