#: 十二表表序（导入/验收共用）
# 九表表序：导入、验收、报告三处共用同一顺序 ────────────────────────────────────
# 元组顺序 = 工作簿里 sheet 的排列顺序，也是「三表在前、九表在后」的交付口径：
# 　1 利润表 / 2 资产负债表 / 3 现金流量表（老师件三表，对外报表面）
# 　4 税金及附加 / 5 销售费用 / 6 管理费用 / 7 费用表月度汇总 / 8 摊销明细 / 9 分录
# 　（旧骨架九表，内部底稿与勾稽依据）
# 为什么不按字母或字典序：版式按业务阅读顺序排（先结果后底稿）；下载模板、导入校验、报告
# 　取证都按本元组遍历，任何一处改序都会让三处的 sheet 下标错位——本元组是硬契约。
# 命名提示：变量与文档沿称「十二表」，因 1.0.5 规划里曾有 12 张（含已下线的收入两表与蓝恐
# 　龙费用，见 _sheng_banshi.py 中 JIU 的注释）；现只留 9 张，名从旧称。
